#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    int vet[6];
    for (int i = 0; i < 6; ++i) {
        cin >> vet[i];
    }

    for (int i = 0; i < 6; ++i) {
        for (int k = i + 1; k < 6; ++k) {
            if (vet[i] > vet[k]) {
                int aux = vet[i];
                vet[i] = vet[k];
                vet[k] = aux;
            }
        }
    }

    for (int i = 0; i + 2 < 6; ++i) {
        if (vet[i] + vet[i + 1] + vet[i + 2] == n) {
            cout << vet[i] << " " << vet[i + 1] << " " << vet[i + 2] << "\n";
            break;
        }
    }

    return 0;
}

